DECLARE  
  clobValue ADPT_INTERFACESOURCE.DBSQL%TYPE;  
BEGIN  
  clobValue := '"SELECT FEEDETAIL.TRADE_ID AS TRADE_ID, DECODE(INFO.FINPROD_MARKET_ID,NULL,      (SELECT PROD.FINPROD_MARKET_ID FROM FIN_PRODUCT_ADD INFOADD     LEFT JOIN FIN_PRODUCT PROD       ON INFOADD.FINPROD_ID = PROD.FINPROD_ID    WHERE INFOADD.PORTFOLIO_ID = DL.FINPROD_ID AND ROWNUM=1),      DECODE(INFO.P_FINPROD_ID, NULL, INFO.FINPROD_MARKET_ID, DL.FINPROD_ID))    AS PROD_ID,      FEINFO.FEE_ID FEE_ID,            DECODE(DL.PS,''C7'',''C02'',DL.FINPROD_TYPE2) feeType,      DL.SETTLE_DATE PAY_DATE,      FEEDETAIL.FEE_AMT PAID_FEE,        DECODE(REVDL.UPDATE_TIME,NULL,''E'',''D'') status,      FEEDETAIL.CREATE_USER,      FEEDETAIL.CREATE_DEPT,      FEEDETAIL.CREATE_TIME,      FEEDETAIL.UPDATE_USER,      FEEDETAIL.UPDATE_TIME     FROM TRD_PRODUCT_DEAL DL          LEFT JOIN FIN_PRODUCT INFO     ON DL.FINPROD_ID = INFO.FINPROD_ID          LEFT JOIN TRD_PRODUCT_DEAL REVDL     ON DL.TRADE_ID = REVDL.P_TRADE_ID          LEFT JOIN TRD_TRADE_FEE_DETAIL FEEDETAIL     ON DL.TRADE_ID = FEEDETAIL.TRADE_ID          LEFT JOIN MST_FEEINFO FEINFO     ON FEINFO.FEE_ID = FEEDETAIL.FEE_ID          WHERE (DL.PS=''C7'' OR     (DL.PS = ''C11''      AND DL.FINPROD_TYPE2 IN (''C03'',''C04'',''C05'',''C06'',''C09'',''C10'',''C11'')))     AND DL.IS_CANCEL IS NOT NULL     AND FEEDETAIL.UPDATE_TIME >:UPDATE" '; --字段内容  
  UPDATE ADPT_INTERFACESOURCE T SET T.DBSQL = clobValue WHERE sourceid='1023';  
  COMMIT;  
END;  